from scipy.optimize import least_squares
def build(p):
    g,e,q,pp,f1=p
    cols=[t,1/((1+g*x)*v),x**q*np.exp(-e*x),t*v**pp]
    return np.column_stack(cols)
def resid(p):
    X=build(p)
    c,_,_,_=np.linalg.lstsq(X,dv_dt,rcond=None)
    return X@c-dv_dt
